"""Launch the supplied working thermal and ONNX viewers in isolated processes.

Run: python combined_pig_viewers_v3.py --model best.onnx
Requires the same environment as the original working scripts.
No torch, ultralytics, or imports from the original .py files are required.
Two camera windows plus a controller open. Stop both using the controller.

Version 3: webcam display capped at 10 FPS and 480x360.
SPI acquisition has its own process and shared latest-frame buffer.
Pi 4 affinity: thermal acquisition on last available CPU, thermal GUI on first,
YOLO on middle CPUs. This reduces competition; it is not real-time scheduling
and cannot guarantee VoSPI timing or repair power/wiring problems.
Thermal region IDs are NOT matched to RGB pig IDs. No SMS or fusion is added.
Temperature conversion still requires confirmed TLinear mode/resolution;
a plausible numeric range alone does not verify radiometric configuration.
"""
import argparse
import os
from pathlib import Path
import signal
import subprocess
import sys
import time
import types
THERMAL_SOURCE = '#!/usr/bin/env python3\n"""Optimized multi-region FLIR Lepton 3.1R temperature viewer.\n\nDesigned for Raspberry Pi 4B and FLIR Lepton 3.1R on SPI0 CE0.\n\nThe program detects separate warm regions in the thermal image, gives each\nregion a temporary Thermal ID, and displays a temporally smoothed surface\ntemperature. A thermal region is not guaranteed to be one pig: touching pigs\ncan merge and other warm objects can be detected. Reliable per-pig identity\nrequires RGB YOLO detections plus calibrated RGB-to-thermal registration.\n\nTemperature is valid only when the Lepton is outputting TLinear radiometric\npixels. The displayed value is surface temperature, not rectal/core body\ntemperature.\n"""\n\nfrom dataclasses import dataclass\nimport json\nimport fcntl\nimport os\nimport queue\nimport threading\nimport time\nimport tkinter as tk\nfrom tkinter import messagebox\n\nimport cv2\nimport numpy as np\nimport spidev\nfrom PIL import Image, ImageDraw, ImageTk\n\n\n# ---------------------------------------------------------------------------\n# FLIR Lepton / SPI configuration\n# ---------------------------------------------------------------------------\nSPI_BUS = 0\nSPI_DEVICE = 0\nSPI_SPEED_HZ = 18_000_000\nPACKET_SIZE = 164\nPACKETS_PER_SEGMENT = 60\nWIDTH = 160\nHEIGHT = 120\nCAPTURE_TIMEOUT = 2.0\nRESYNC_DELAY_SECONDS = 0.25\n\n# ---------------------------------------------------------------------------\n# Display and radiometry\n# ---------------------------------------------------------------------------\nDISPLAY_SCALE = 4\nGUI_UPDATE_MS = 30\nTLINEAR_K_PER_COUNT = 0.01\n\n# Calibrate this against a trusted reference at the intended distance.\n# corrected temperature = measured temperature + offset\nTEMPERATURE_OFFSET_C = 0.0\n\n# ---------------------------------------------------------------------------\n# Warm-region detection\n# ---------------------------------------------------------------------------\n# A region must be warmer than the frame median by at least this amount.\nMINIMUM_DELTA_ABOVE_MEDIAN_C = 1.0\n\n# Ignore extremely small blobs and a blob covering almost the whole image.\nMINIMUM_REGION_AREA_PIXELS = 100\nMAXIMUM_REGION_AREA_PIXELS = int(WIDTH * HEIGHT * 0.80)\n\n# A robust high percentile estimates warm body surface without trusting a\n# single noisy maximum pixel.\nREGION_TEMPERATURE_PERCENTILE = 90.0\n\n# Tracking and temperature smoothing.\nMAX_TRACK_DISTANCE_PIXELS = 28.0\nMAX_MISSED_FRAMES = 12\nMINIMUM_TRACK_HITS = 2\nTEMPERATURE_EMA_ALPHA = 0.25\n\n# Surface-temperature alert threshold used for the High Temperature counter.\n# This is a configurable surface-temperature threshold, not a core/rectal\n# body-temperature diagnosis. Adjust it for your camera/calibration setup.\nHIGH_TEMPERATURE_THRESHOLD_C = 35.0\n\n# A condition must remain detected this long before it is counted.\nEVENT_CONFIRMATION_SEC = 1.0\n\n\ndef publish_controller_metrics(**metrics):\n    """Merge non-counter status values into the shared parent UI file."""\n    path = os.environ.get("PIG_STATUS_PATH")\n    if not path:\n        return\n    try:\n        with open(path, "a+", encoding="utf-8") as handle:\n            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)\n            try:\n                handle.seek(0)\n                try:\n                    payload = json.load(handle)\n                except (json.JSONDecodeError, ValueError):\n                    payload = {}\n                if not isinstance(payload, dict):\n                    payload = {}\n                payload.update(metrics)\n                payload["timestamp"] = time.time()\n                handle.seek(0)\n                handle.truncate()\n                json.dump(payload, handle)\n                handle.flush()\n                os.fsync(handle.fileno())\n            finally:\n                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)\n    except OSError:\n        pass\n\n\ndef increment_controller_metric(field, amount=1):\n    """Atomically increment a cumulative controller counter."""\n    path = os.environ.get("PIG_STATUS_PATH")\n    if not path:\n        return 0\n    try:\n        with open(path, "a+", encoding="utf-8") as handle:\n            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)\n            try:\n                handle.seek(0)\n                try:\n                    payload = json.load(handle)\n                except (json.JSONDecodeError, ValueError):\n                    payload = {}\n                if not isinstance(payload, dict):\n                    payload = {}\n                total = max(0, int(payload.get(field, 0))) + int(amount)\n                payload[field] = total\n                payload["timestamp"] = time.time()\n                handle.seek(0)\n                handle.truncate()\n                json.dump(payload, handle)\n                handle.flush()\n                os.fsync(handle.fileno())\n                return total\n            finally:\n                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)\n    except (OSError, TypeError, ValueError):\n        return 0\n\n\n\ndef read_controller_metric(field):\n    path = os.environ.get("PIG_STATUS_PATH")\n    if not path:\n        return 0\n    try:\n        with open(path, "r", encoding="utf-8") as handle:\n            payload = json.load(handle)\n        return max(0, int(payload.get(field, 0)))\n    except (OSError, ValueError, TypeError):\n        return 0\n\ndef colour_map(gray):\n    """Convert an 8-bit grayscale frame to an RGB thermal colour map."""\n    x = gray.astype(np.int16)\n    red = np.clip(2 * x - 128, 0, 255)\n    blue = np.clip(255 - 2 * x, 0, 255)\n    green = 255 - np.abs(2 * x - 255)\n    return np.dstack((red, green, blue)).astype(np.uint8)\n\n\ndef raw_to_celsius(raw):\n    """Convert Kelvin x100 TLinear pixels to degrees Celsius."""\n    return (\n        raw.astype(np.float32) * TLINEAR_K_PER_COUNT\n        - 273.15\n        + TEMPERATURE_OFFSET_C\n    )\n\n\ndef temperatures_are_plausible(celsius):\n    """Reject non-TLinear data instead of displaying false temperatures."""\n    median = float(np.median(celsius))\n    return -80.0 <= median <= 250.0\n\n\nclass Lepton3:\n    def __init__(self):\n        self.spi = None\n        self.frame_counter = 0\n        self.error_counter = 0\n        self.last_error = ""\n        self.zero_packet = [0] * PACKET_SIZE\n        self._open()\n\n    def _open(self):\n        self.spi = spidev.SpiDev()\n        self.spi.open(SPI_BUS, SPI_DEVICE)\n        self.spi.mode = 3\n        self.spi.max_speed_hz = SPI_SPEED_HZ\n        self.spi.bits_per_word = 8\n\n    def resync(self):\n        try:\n            if self.spi is not None:\n                self.spi.close()\n        except Exception:\n            pass\n        time.sleep(RESYNC_DELAY_SECONDS)\n        self._open()\n\n    def read_packet(self):\n        return self.spi.xfer2([0]*PACKET_SIZE)\n\n    def capture(self, timeout=CAPTURE_TIMEOUT):\n        frame = np.zeros((HEIGHT, WIDTH), dtype=np.uint16)\n        expected_segment = 1\n        deadline = time.monotonic() + timeout\n\n        while time.monotonic() < deadline:\n            packets = []\n\n            for expected_packet in range(PACKETS_PER_SEGMENT):\n                packet = self.read_packet()\n\n                if len(packet) != PACKET_SIZE:\n                    packets = []\n                    break\n                if (packet[0] & 0x0F) == 0x0F:\n                    packets = []\n                    break\n\n                packet_number = ((packet[0] & 0x0F) << 8) | packet[1]\n                if packet_number != expected_packet:\n                    packets = []\n                    break\n                packets.append(packet)\n\n            if len(packets) != PACKETS_PER_SEGMENT:\n                continue\n\n            segment = (packets[20][0] >> 4) & 0x07\n            if segment not in (1, 2, 3, 4):\n                continue\n\n            if segment != expected_segment:\n                expected_segment = 1\n                if segment != 1:\n                    continue\n\n            for packet_number, packet in enumerate(packets):\n                row = (segment - 1) * 30 + packet_number // 2\n                column = (packet_number % 2) * 80\n                payload = np.frombuffer(bytes(packet[4:]), dtype=">u2")\n                frame[row, column:column + 80] = payload\n\n            expected_segment += 1\n            if expected_segment == 5:\n                self.frame_counter += 1\n                self.last_error = ""\n                return frame\n\n        self.error_counter += 1\n        self.last_error = "VoSPI synchronization timeout"\n        self.resync()\n        return None\n\n    def close(self):\n        try:\n            if self.spi is not None:\n                self.spi.close()\n        except Exception:\n            pass\n\n\n@dataclass\nclass Detection:\n    box: tuple\n    center: tuple\n    area: int\n    temperature: float\n    maximum: float\n\n\n@dataclass\nclass ThermalTrack:\n    box: tuple\n    center: tuple\n    temperature: float\n    maximum: float\n    hits: int = 1\n    missed: int = 0\n\n\ndef detect_warm_regions(celsius):\n    """Return filtered warm regions and their robust surface temperatures."""\n    smoothed = cv2.GaussianBlur(celsius, (5, 5), 0)\n    scene_median = float(np.median(smoothed))\n    percentile_threshold = float(np.percentile(smoothed, 70))\n    threshold = max(\n        scene_median + MINIMUM_DELTA_ABOVE_MEDIAN_C,\n        percentile_threshold,\n    )\n\n    mask = (smoothed >= threshold).astype(np.uint8) * 255\n    kernel = np.ones((3, 3), dtype=np.uint8)\n    mask = cv2.morphologyEx(mask, cv2.MORPH_OPEN, kernel, iterations=1)\n    mask = cv2.morphologyEx(mask, cv2.MORPH_CLOSE, kernel, iterations=2)\n\n    count, labels, stats, centroids = cv2.connectedComponentsWithStats(\n        mask,\n        connectivity=8,\n    )\n\n    detections = []\n    for label_index in range(1, count):\n        x, y, width, height, area = stats[label_index]\n        area = int(area)\n        if not (MINIMUM_REGION_AREA_PIXELS <= area <= MAXIMUM_REGION_AREA_PIXELS):\n            continue\n\n        region_values = celsius[labels == label_index]\n        if region_values.size == 0:\n            continue\n\n        # Discard cooler edge pixels so flooring/background within an irregular\n        # component does not pull the body-surface estimate downward.\n        core_cutoff = float(np.percentile(region_values, 50))\n        core_values = region_values[region_values >= core_cutoff]\n        if core_values.size == 0:\n            core_values = region_values\n\n        robust_temperature = float(np.percentile(\n            core_values,\n            REGION_TEMPERATURE_PERCENTILE,\n        ))\n        robust_maximum = float(np.percentile(region_values, 99))\n        center_x, center_y = centroids[label_index]\n\n        detections.append(Detection(\n            box=(int(x), int(y), int(x + width), int(y + height)),\n            center=(float(center_x), float(center_y)),\n            area=area,\n            temperature=robust_temperature,\n            maximum=robust_maximum,\n        ))\n\n    detections.sort(key=lambda item: item.area, reverse=True)\n    return detections, threshold, mask\n\n\nclass ThermalTracker:\n    """Lightweight nearest-centre tracker for separate thermal regions."""\n\n    def __init__(self):\n        self.tracks = {}\n        self.next_id = 1\n\n    def update(self, detections):\n        candidates = []\n        for track_id, track in self.tracks.items():\n            for detection_index, detection in enumerate(detections):\n                distance = float(np.hypot(\n                    track.center[0] - detection.center[0],\n                    track.center[1] - detection.center[1],\n                ))\n                if distance <= MAX_TRACK_DISTANCE_PIXELS:\n                    candidates.append((distance, track_id, detection_index))\n\n        candidates.sort()\n        used_tracks = set()\n        used_detections = set()\n\n        for _, track_id, detection_index in candidates:\n            if track_id in used_tracks or detection_index in used_detections:\n                continue\n            detection = detections[detection_index]\n            track = self.tracks[track_id]\n            track.box = detection.box\n            track.center = detection.center\n            track.temperature = (\n                (1.0 - TEMPERATURE_EMA_ALPHA) * track.temperature\n                + TEMPERATURE_EMA_ALPHA * detection.temperature\n            )\n            track.maximum = detection.maximum\n            track.hits += 1\n            track.missed = 0\n            used_tracks.add(track_id)\n            used_detections.add(detection_index)\n\n        for track_id in list(self.tracks):\n            if track_id not in used_tracks:\n                self.tracks[track_id].missed += 1\n                if self.tracks[track_id].missed > MAX_MISSED_FRAMES:\n                    del self.tracks[track_id]\n\n        for detection_index, detection in enumerate(detections):\n            if detection_index in used_detections:\n                continue\n            self.tracks[self.next_id] = ThermalTrack(\n                box=detection.box,\n                center=detection.center,\n                temperature=detection.temperature,\n                maximum=detection.maximum,\n            )\n            self.next_id += 1\n\n        return {\n            track_id: track\n            for track_id, track in self.tracks.items()\n            if track.hits >= MINIMUM_TRACK_HITS and track.missed == 0\n        }\n\n\nclass LeptonViewer:\n    def __init__(self, root):\n        self.root = root\n        self.root.title("FLIR Lepton 3.1R Multi-Region Temperature Viewer")\n        self.running = True\n        self.high_temperature_event_state = {}\n        self.camera = Lepton3()\n        self.tracker = ThermalTracker()\n        self.frame_queue = queue.Queue(maxsize=1)\n        self.last_frame_time = None\n        self.smoothed_fps = 0.0\n\n        self.image_label = tk.Label(root, bg="black")\n        self.image_label.pack(padx=8, pady=8)\n\n        self.temperature_label = tk.Label(\n            root,\n            text="Waiting for a radiometric frame...",\n            font=("TkDefaultFont", 11, "bold"),\n        )\n        self.temperature_label.pack(pady=(0, 4))\n\n        self.status_label = tk.Label(root, text="Initializing...")\n        self.status_label.pack(pady=(0, 8))\n\n        self.root.protocol("WM_DELETE_WINDOW", self.close)\n        self.camera_thread = threading.Thread(\n            target=self._camera_loop,\n            daemon=True,\n        )\n        self.camera_thread.start()\n        self.root.after(GUI_UPDATE_MS, self._gui_update)\n\n    def _replace_latest_frame(self, raw):\n        try:\n            self.frame_queue.get_nowait()\n        except queue.Empty:\n            pass\n        try:\n            self.frame_queue.put_nowait(raw)\n        except queue.Full:\n            pass\n\n    def _camera_loop(self):\n        while self.running:\n            try:\n                raw = self.camera.capture()\n                if raw is not None:\n                    self._replace_latest_frame(raw)\n            except Exception as error:\n                self.camera.error_counter += 1\n                self.camera.last_error = str(error)\n                time.sleep(0.25)\n                try:\n                    self.camera.resync()\n                except Exception as reopen_error:\n                    self.camera.last_error = str(reopen_error)\n\n    def _gui_update(self):\n        if not self.running:\n            return\n\n        newest = None\n        while True:\n            try:\n                newest = self.frame_queue.get_nowait()\n            except queue.Empty:\n                break\n\n        if newest is not None:\n            self._display_frame(newest)\n        elif self.camera.last_error:\n            self.status_label.configure(\n                text=f"Synchronizing: {self.camera.last_error} | "\n                     f"Errors: {self.camera.error_counter}"\n            )\n\n        self.root.after(GUI_UPDATE_MS, self._gui_update)\n\n    def _display_frame(self, raw):\n        celsius = raw_to_celsius(raw)\n        if not temperatures_are_plausible(celsius):\n            self.temperature_label.configure(\n                text=(\n                    "Temperature unavailable: frame is not valid TLinear data "\n                    f"(raw median {int(np.median(raw))})"\n                ),\n                fg="red",\n            )\n            return\n\n        low = float(np.percentile(raw, 2))\n        high = float(np.percentile(raw, 98))\n        if high <= low:\n            high = low + 1.0\n\n        gray = np.clip(\n            (raw.astype(np.float32) - low) * 255.0 / (high - low),\n            0,\n            255,\n        ).astype(np.uint8)\n        rgb = colour_map(gray)\n\n        detections, threshold, _ = detect_warm_regions(celsius)\n        tracks = self.tracker.update(detections)\n\n        image = Image.fromarray(rgb, "RGB").resize(\n            (WIDTH * DISPLAY_SCALE, HEIGHT * DISPLAY_SCALE),\n            Image.Resampling.NEAREST,\n        )\n        draw = ImageDraw.Draw(image)\n\n        temperature_summary = []\n        high_temperature_count = 0\n        now_for_events = time.monotonic()\n        current_track_ids = set(tracks.keys())\n        for stale_id in set(self.high_temperature_event_state) - current_track_ids:\n            del self.high_temperature_event_state[stale_id]\n\n        for track_id, track in tracks.items():\n            x1, y1, x2, y2 = track.box\n            scaled_box = tuple(\n                int(value * DISPLAY_SCALE)\n                for value in (x1, y1, x2, y2)\n            )\n            is_high_temperature = track.temperature >= HIGH_TEMPERATURE_THRESHOLD_C\n            if is_high_temperature:\n                high_temperature_count += 1\n                event_state = self.high_temperature_event_state.get(track_id)\n                if event_state is None:\n                    event_state = {"since": now_for_events, "counted": False}\n                    self.high_temperature_event_state[track_id] = event_state\n                if (\n                    not event_state["counted"]\n                    and now_for_events - event_state["since"] >= EVENT_CONFIRMATION_SEC\n                ):\n                    increment_controller_metric("high_temperature", 1)\n                    event_state["counted"] = True\n            else:\n                self.high_temperature_event_state.pop(track_id, None)\n            label_prefix = "HIGH TEMP" if is_high_temperature else "Thermal"\n            label = f"{label_prefix} ID {track_id}: {track.temperature:.2f} C"\n\n            draw.rectangle(scaled_box, outline="white", width=2)\n            text_x = scaled_box[0] + 3\n            text_y = max(3, scaled_box[1] - 14)\n            text_width = min(250, max(150, len(label) * 7))\n            draw.rectangle(\n                (text_x - 2, text_y - 2, text_x + text_width, text_y + 12),\n                fill="black",\n            )\n            draw.text((text_x, text_y), label, fill="white")\n            temperature_summary.append(\n                f"ID {track_id}: {track.temperature:.2f} °C"\n            )\n\n\n        high_temperature_total = read_controller_metric("high_temperature")\n        if temperature_summary:\n            self.temperature_label.configure(\n                text=(\n                    f"High Temperature total: {high_temperature_total} | "\n                    + "   |   ".join(temperature_summary)\n                ),\n                fg="dark red" if high_temperature_count else "dark green",\n            )\n        else:\n            self.temperature_label.configure(\n                text=f"High Temperature total: {high_temperature_total} | No stable warm regions detected",\n                fg="dark orange",\n            )\n\n        now = time.perf_counter()\n        if self.last_frame_time is not None:\n            instant_fps = 1.0 / max(now - self.last_frame_time, 1e-6)\n            self.smoothed_fps = (\n                instant_fps if self.smoothed_fps == 0.0\n                else 0.9 * self.smoothed_fps + 0.1 * instant_fps\n            )\n        self.last_frame_time = now\n\n        self.photo = ImageTk.PhotoImage(image)\n        self.image_label.configure(image=self.photo)\n        self.status_label.configure(\n            text=(\n                f"Regions: {len(tracks)} | High Temperature total: {high_temperature_total} | "\n                f"Frames: {self.camera.frame_counter} | Errors: {self.camera.error_counter} | "\n                f"Warm-region threshold: {threshold:.2f} °C | "\n                f"High-temp limit: {HIGH_TEMPERATURE_THRESHOLD_C:.1f} °C | "\n                f"Display: {self.smoothed_fps:.1f} FPS"\n            )\n        )\n\n    def close(self):\n        self.running = False\n        self.camera_thread.join(timeout=3.0)\n        if not self.camera_thread.is_alive():\n            self.camera.close()\n        self.root.destroy()\n\n\ndef main():\n    root = tk.Tk()\n    try:\n        LeptonViewer(root)\n    except PermissionError:\n        messagebox.showerror(\n            "SPI permission denied",\n            "Add the current user to the spi group, then log out or reboot.",\n        )\n        root.destroy()\n        return\n    except FileNotFoundError:\n        messagebox.showerror(\n            "SPI not found",\n            "/dev/spidev0.0 was not found. Enable SPI using raspi-config.",\n        )\n        root.destroy()\n        return\n\n    root.mainloop()\n\n\n'
YOLO_SOURCE = '#!/usr/bin/env python3\n"""Responsive pig detector/tracker with model-based laying timer.\n\nDesigned for Raspberry Pi CPU deployment. Uses ONNX Runtime directly.\nThe ONNX model must contain the behavior classes used by the project.\nEach tracked Pig ID has an independent laying timer.\n"""\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\nimport json\nimport fcntl\nimport json\nimport os\nimport queue\nimport threading\nimport time\n\nimport cv2\nimport numpy as np\nimport onnxruntime as ort\n\n\nMODEL_PATH = Path(os.environ["PIG_MODEL_PATH"])\nCAMERA_INDEX = 0\nCAMERA_WIDTH = 640\nCAMERA_HEIGHT = 480\n\nCONFIDENCE_THRESHOLD = 0.93\nNMS_IOU_THRESHOLD = 0.45\nMINIMUM_BOX_AREA = 1500\n\nTRACK_IOU_THRESHOLD = 0.12\nTRACK_CENTER_DISTANCE = 1.25\nTRACK_MAX_MISSED_INFERENCES = 12\nTRACK_VISIBLE_MISSES = 3\nTRACK_TRAIL_LENGTH = 20\nTRACK_MINIMUM_HITS = 2\nCOUNT_CONFIRMATION_UPDATES = 2\n\n# Persistent stable-ID layer.\nMAX_LOST_SEC = 10.0\nBASE_GATE_PX = 150.0\nSPEED_PX_PER_SEC = 120.0\nMAX_GATE_PX = 700.0\nMAX_SIZE_RATIO = 2.5\n\n\ndef publish_controller_metrics(**metrics):\n    """Merge non-counter status values into the shared parent UI file."""\n    path = os.environ.get("PIG_STATUS_PATH")\n    if not path:\n        return\n    try:\n        with open(path, "a+", encoding="utf-8") as handle:\n            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)\n            try:\n                handle.seek(0)\n                try:\n                    payload = json.load(handle)\n                except (json.JSONDecodeError, ValueError):\n                    payload = {}\n                if not isinstance(payload, dict):\n                    payload = {}\n                payload.update(metrics)\n                payload["timestamp"] = time.time()\n                handle.seek(0)\n                handle.truncate()\n                json.dump(payload, handle)\n                handle.flush()\n                os.fsync(handle.fileno())\n            finally:\n                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)\n    except OSError:\n        pass\n\n\ndef increment_controller_metric(field, amount=1):\n    """Atomically increment a cumulative controller counter."""\n    path = os.environ.get("PIG_STATUS_PATH")\n    if not path:\n        return 0\n    try:\n        with open(path, "a+", encoding="utf-8") as handle:\n            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)\n            try:\n                handle.seek(0)\n                try:\n                    payload = json.load(handle)\n                except (json.JSONDecodeError, ValueError):\n                    payload = {}\n                if not isinstance(payload, dict):\n                    payload = {}\n                total = max(0, int(payload.get(field, 0))) + int(amount)\n                payload[field] = total\n                payload["timestamp"] = time.time()\n                handle.seek(0)\n                handle.truncate()\n                json.dump(payload, handle)\n                handle.flush()\n                os.fsync(handle.fileno())\n                return total\n            finally:\n                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)\n    except (OSError, TypeError, ValueError):\n        return 0\nGAP_RESET_SEC = 2.0\n\n# Names are read from the ONNX metadata when available. These aliases let the\n# timer recognize common labels without requiring an exact spelling.\nLAYING_ALIASES = {\n    "laying", "lying", "lie", "laid", "down", "lying_down", "laying_down"\n}\n\n# In the current model, the abnormal-behavior result is the laying/lying\n# behavior already used by the timer. Keep this mapping here so it is easy\n# to extend if the ONNX model later adds more abnormal classes.\nABNORMAL_BEHAVIOR_ALIASES = set(LAYING_ALIASES)\n\n# A condition must remain detected this long before it is counted.\nEVENT_CONFIRMATION_SEC = 1.0\n\n\ndef normalize_class_name(name):\n    return str(name).strip().lower().replace("-", "_").replace(" ", "_")\n\n\ndef is_laying_class(name):\n    normalized = normalize_class_name(name)\n    return normalized in LAYING_ALIASES or "lying" in normalized or "laying" in normalized\n\n\ndef is_abnormal_behavior_class(name):\n    normalized = normalize_class_name(name)\n    return (\n        normalized in ABNORMAL_BEHAVIOR_ALIASES\n        or is_laying_class(normalized)\n    )\n\n\ndef stable_colour(track_id):\n    generator = np.random.default_rng(track_id * 1009)\n    colour = generator.integers(70, 256, size=3, dtype=np.uint8)\n    return tuple(int(value) for value in colour)\n\n\ndef letterbox(image, target_width, target_height):\n    height, width = image.shape[:2]\n    scale = min(target_width / width, target_height / height)\n    resized_width = int(round(width * scale))\n    resized_height = int(round(height * scale))\n    resized = cv2.resize(image, (resized_width, resized_height), interpolation=cv2.INTER_LINEAR)\n    pad_x = (target_width - resized_width) // 2\n    pad_y = (target_height - resized_height) // 2\n    canvas = np.full((target_height, target_width, 3), 114, dtype=np.uint8)\n    canvas[pad_y:pad_y + resized_height, pad_x:pad_x + resized_width] = resized\n    return canvas, scale, pad_x, pad_y\n\n\ndef box_iou(first, second):\n    ax1, ay1, ax2, ay2 = first\n    bx1, by1, bx2, by2 = second\n    intersection_width = max(0.0, min(ax2, bx2) - max(ax1, bx1))\n    intersection_height = max(0.0, min(ay2, by2) - max(ay1, by1))\n    intersection = intersection_width * intersection_height\n    first_area = max(0.0, ax2 - ax1) * max(0.0, ay2 - ay1)\n    second_area = max(0.0, bx2 - bx1) * max(0.0, by2 - by1)\n    union = first_area + second_area - intersection\n    return intersection / union if union > 0.0 else 0.0\n\n\ndef normalized_center_distance(first, second):\n    first_center = np.array([(first[0] + first[2]) / 2.0, (first[1] + first[3]) / 2.0])\n    second_center = np.array([(second[0] + second[2]) / 2.0, (second[1] + second[3]) / 2.0])\n    first_size = max(first[2] - first[0], first[3] - first[1])\n    second_size = max(second[2] - second[0], second[3] - second[1])\n    reference_size = max((first_size + second_size) / 2.0, 1.0)\n    return float(np.linalg.norm(first_center - second_center) / reference_size)\n\n\n@dataclass\nclass Track:\n    box: np.ndarray\n    confidence: float\n    class_id: int\n    class_name: str\n    missed: int\n    trail: list\n    hits: int\n    laying_since: float | None = None\n    laying_seconds: float = 0.0\n\n\nclass StableIDMapper:\n    """Re-attach raw tracker IDs to persistent pig IDs after tracker resets."""\n\n    def __init__(self, fps_hint=10.0):\n        self.fps_hint = max(float(fps_hint), 1.0)\n        self.raw_to_stable = {}\n        self.last = {}  # stable_id -> center/w/h/monotonic time\n        self.next_id = 1\n\n    @staticmethod\n    def _geom(det):\n        x1, y1, x2, y2 = [float(v) for v in det["box"]]\n        return ((x1 + x2) / 2.0, (y1 + y2) / 2.0), max(x2 - x1, 1.0), max(y2 - y1, 1.0)\n\n    def _cost(self, det, sid, now):\n        (cx, cy), w, h = self._geom(det)\n        prev = self.last[sid]\n        px, py = prev["center"]\n        dt = max(0.0, now - prev["time"])\n        gate = min(max(BASE_GATE_PX, 0.8 * max(w, h)) + SPEED_PX_PER_SEC * dt, MAX_GATE_PX)\n        distance = float(np.hypot(cx - px, cy - py))\n        if distance > gate:\n            return None\n        ratio = (w * h) / max(prev["w"] * prev["h"], 1.0)\n        if ratio > MAX_SIZE_RATIO or ratio < 1.0 / MAX_SIZE_RATIO:\n            return None\n        size_delta = abs(np.log(max(ratio, 1e-6))) / np.log(MAX_SIZE_RATIO)\n        return distance / gate + 0.15 * size_delta\n\n    def update(self, detections, now):\n        claimed = set()\n        pending = []\n        for det in detections:\n            raw = int(det["track_id"])\n            sid = self.raw_to_stable.get(raw)\n            if raw != -1 and sid is not None and sid not in claimed:\n                claimed.add(sid)\n                det["raw_id"] = raw\n                det["track_id"] = sid\n            else:\n                pending.append(det)\n\n        candidates = [sid for sid, info in self.last.items()\n                      if sid not in claimed and 0.0 <= now - info["time"] <= MAX_LOST_SEC]\n        matches = {}\n        if pending and candidates:\n            inf = 1e6\n            cost = np.full((len(pending), len(candidates)), inf, dtype=np.float64)\n            for i, det in enumerate(pending):\n                for j, sid in enumerate(candidates):\n                    value = self._cost(det, sid, now)\n                    if value is not None:\n                        cost[i, j] = value\n            # Greedy minimum-cost one-to-one assignment keeps this deployment SciPy-free.\n            # For the small number of pigs expected here, this is lightweight and stable.\n            edges = []\n            for row in range(cost.shape[0]):\n                for col in range(cost.shape[1]):\n                    if cost[row, col] < inf:\n                        edges.append((float(cost[row, col]), row, col))\n            edges.sort(key=lambda item: item[0])\n            used_rows = set()\n            used_cols = set()\n            for _, row, col in edges:\n                if row in used_rows or col in used_cols:\n                    continue\n                matches[row] = candidates[col]\n                used_rows.add(row)\n                used_cols.add(col)\n\n        for i, det in enumerate(pending):\n            raw = int(det["track_id"])\n            sid = matches.get(i)\n            if sid is None:\n                sid = self.next_id\n                self.next_id += 1\n            self.raw_to_stable[raw] = sid\n            claimed.add(sid)\n            det["raw_id"] = raw\n            det["track_id"] = sid\n\n        for det in detections:\n            sid = int(det["track_id"])\n            if sid == -1:\n                continue\n            (cx, cy), w, h = self._geom(det)\n            previous = self.last.get(sid)\n            det["gap_seconds"] = max(0.0, now - previous["time"]) if previous else None\n            self.last[sid] = {"center": (cx, cy), "w": w, "h": h, "time": now}\n        return detections\n\n\nclass IoUTracker:\n    def __init__(self):\n        self.tracks = {}\n        self.next_id = 1\n\n    def _set_behavior(self, track, class_id, class_name, now):\n        was_laying = is_laying_class(track.class_name)\n        now_laying = is_laying_class(class_name)\n        track.class_id = class_id\n        track.class_name = class_name\n        if now_laying:\n            if not was_laying or track.laying_since is None:\n                track.laying_since = now\n            track.laying_seconds = max(0.0, now - track.laying_since)\n        else:\n            track.laying_since = None\n            track.laying_seconds = 0.0\n\n    def update(self, detections, now):\n        # detections contains (box_xyxy, confidence, class_id, class_name).\n        candidates = []\n        for track_id, track in self.tracks.items():\n            for detection_index, (box, _, _, _) in enumerate(detections):\n                overlap = box_iou(track.box, box)\n                center_distance = normalized_center_distance(track.box, box)\n                if overlap >= TRACK_IOU_THRESHOLD or center_distance <= TRACK_CENTER_DISTANCE:\n                    score = overlap + 0.25 / (1.0 + center_distance)\n                    candidates.append((score, track_id, detection_index))\n\n        candidates.sort(reverse=True)\n        used_tracks = set()\n        used_detections = set()\n\n        for _, track_id, detection_index in candidates:\n            if track_id in used_tracks or detection_index in used_detections:\n                continue\n            box, confidence, class_id, class_name = detections[detection_index]\n            track = self.tracks[track_id]\n            track.box = box\n            track.confidence = confidence\n            track.missed = 0\n            track.hits += 1\n            center = (int((box[0] + box[2]) / 2), int((box[1] + box[3]) / 2))\n            track.trail.append(center)\n            track.trail = track.trail[-TRACK_TRAIL_LENGTH:]\n            self._set_behavior(track, class_id, class_name, now)\n            used_tracks.add(track_id)\n            used_detections.add(detection_index)\n\n        for track_id, track in list(self.tracks.items()):\n            if track_id not in used_tracks:\n                track.missed += 1\n                if track.missed > TRACK_MAX_MISSED_INFERENCES:\n                    del self.tracks[track_id]\n\n        for detection_index, (box, confidence, class_id, class_name) in enumerate(detections):\n            if detection_index in used_detections:\n                continue\n            center = (int((box[0] + box[2]) / 2), int((box[1] + box[3]) / 2))\n            laying_since = now if is_laying_class(class_name) else None\n            self.tracks[self.next_id] = Track(\n                box=box,\n                confidence=confidence,\n                class_id=class_id,\n                class_name=class_name,\n                missed=0,\n                trail=[center],\n                hits=1,\n                laying_since=laying_since,\n                laying_seconds=0.0,\n            )\n            self.next_id += 1\n\n        visible = {}\n        for track_id, track in self.tracks.items():\n            if track.hits >= TRACK_MINIMUM_HITS and track.missed <= TRACK_VISIBLE_MISSES:\n                if is_laying_class(track.class_name) and track.laying_since is not None:\n                    track.laying_seconds = max(0.0, now - track.laying_since)\n                visible[track_id] = track\n        return visible\n\n\nclass YoloOnnxDetector:\n    def __init__(self, model_path, intra_threads=4):\n        if not model_path.exists():\n            raise FileNotFoundError(\n                f"Model not found: {model_path}\\n"\n                "Place best.onnx beside this file, or use --model PATH."\n            )\n\n        options = ort.SessionOptions()\n        options.graph_optimization_level = ort.GraphOptimizationLevel.ORT_ENABLE_ALL\n        options.execution_mode = ort.ExecutionMode.ORT_SEQUENTIAL\n        options.intra_op_num_threads = int(os.environ.get("PIG_YOLO_THREADS", "2"))\n        options.add_session_config_entry("session.intra_op.allow_spinning", "0")\n        options.add_session_config_entry("session.inter_op.allow_spinning", "0")\n        options.inter_op_num_threads = 1\n\n        self.session = ort.InferenceSession(\n            str(model_path), sess_options=options, providers=["CPUExecutionProvider"]\n        )\n        model_input = self.session.get_inputs()[0]\n        self.input_name = model_input.name\n        shape = model_input.shape\n        if not isinstance(shape[2], int) or not isinstance(shape[3], int):\n            raise RuntimeError(f"Unsupported dynamic model input shape: {shape}")\n        self.input_height = int(shape[2])\n        self.input_width = int(shape[3])\n        self.output_names = [output.name for output in self.session.get_outputs()]\n        self.class_names = self._load_class_names()\n\n        print(f"Loaded: {model_path}")\n        print(f"Actual ONNX input: {self.input_width}x{self.input_height}")\n        print(f"Model classes: {self.class_names}")\n        laying = [name for name in self.class_names if is_laying_class(name)]\n        if laying:\n            print(f"Laying class(es): {laying}")\n        else:\n            print("WARNING: no laying class was found in ONNX class names.")\n\n    def _load_class_names(self):\n        metadata = self.session.get_modelmeta().custom_metadata_map or {}\n        raw_names = metadata.get("names") or metadata.get("classes") or metadata.get("class_names")\n        if raw_names:\n            try:\n                parsed = json.loads(raw_names)\n                if isinstance(parsed, dict):\n                    return [str(parsed[str(i)] if str(i) in parsed else parsed.get(i, i)) for i in range(len(parsed))]\n                if isinstance(parsed, list):\n                    return [str(x) for x in parsed]\n            except Exception:\n                pass\n            if "," in raw_names:\n                return [part.strip() for part in raw_names.split(",")]\n\n        env_names = os.environ.get("PIG_CLASS_NAMES", "").strip()\n        if env_names:\n            return [part.strip() for part in env_names.split(",") if part.strip()]\n\n        # Infer class count from standard YOLO segmentation output\n        # ([1, 4 + classes + 32, anchors]) when metadata is absent.\n        try:\n            output_shape = self.session.get_outputs()[0].shape\n            dimensions = [int(d) for d in output_shape if isinstance(d, int)]\n            candidate_dim = next((d for d in dimensions if 36 < d < 1000), None)\n            inferred_count = candidate_dim - 36 if candidate_dim is not None else 1\n            if inferred_count == 1:\n                return ["pig"]\n            if inferred_count == 2:\n                return ["standing", "laying"]\n            return [f"class_{i}" for i in range(max(1, inferred_count))]\n        except Exception:\n            return ["standing", "laying"]\n\n    def detect(self, frame):\n        prepared, scale, pad_x, pad_y = letterbox(frame, self.input_width, self.input_height)\n        rgb = cv2.cvtColor(prepared, cv2.COLOR_BGR2RGB)\n        tensor = np.ascontiguousarray(rgb.transpose(2, 0, 1)[None].astype(np.float32) / 255.0)\n\n        started = time.perf_counter()\n        outputs = self.session.run(self.output_names, {self.input_name: tensor})\n        inference_ms = (time.perf_counter() - started) * 1000.0\n        prediction = np.squeeze(outputs[0])\n        if prediction.ndim != 2:\n            raise RuntimeError(f"Unexpected detection output: {outputs[0].shape}")\n        if prediction.shape[0] < prediction.shape[1]:\n            prediction = prediction.T\n\n        class_count = len(self.class_names)\n        if prediction.shape[1] < 4 + class_count:\n            raise RuntimeError(\n                f"Model output has {prediction.shape[1]} values per candidate, "\n                f"but {class_count} classes were configured. Check PIG_CLASS_NAMES."\n            )\n\n        boxes_xywh = prediction[:, :4]\n        class_scores = prediction[:, 4:4 + class_count]\n        class_ids = np.argmax(class_scores, axis=1)\n        scores = class_scores[np.arange(len(class_scores)), class_ids]\n        selected = scores >= CONFIDENCE_THRESHOLD\n        boxes_xywh = boxes_xywh[selected]\n        scores = scores[selected]\n        class_ids = class_ids[selected]\n\n        frame_height, frame_width = frame.shape[:2]\n        nms_boxes = []\n        converted_boxes = []\n        converted_scores = []\n        converted_classes = []\n\n        for box, score, class_id in zip(boxes_xywh, scores, class_ids):\n            center_x, center_y, width, height = (float(value) for value in box)\n            x1 = (center_x - width / 2.0 - pad_x) / scale\n            y1 = (center_y - height / 2.0 - pad_y) / scale\n            x2 = (center_x + width / 2.0 - pad_x) / scale\n            y2 = (center_y + height / 2.0 - pad_y) / scale\n            x1 = float(np.clip(x1, 0, frame_width - 1))\n            y1 = float(np.clip(y1, 0, frame_height - 1))\n            x2 = float(np.clip(x2, 0, frame_width - 1))\n            y2 = float(np.clip(y2, 0, frame_height - 1))\n            box_width = x2 - x1\n            box_height = y2 - y1\n            if box_width * box_height < MINIMUM_BOX_AREA:\n                continue\n            nms_boxes.append([int(x1), int(y1), int(box_width), int(box_height)])\n            converted_boxes.append(np.array([x1, y1, x2, y2], dtype=np.float32))\n            converted_scores.append(float(score))\n            converted_classes.append(int(class_id))\n\n        if not nms_boxes:\n            return [], inference_ms\n\n        # NMS per class so standing/laying detections do not suppress each other.\n        kept_global = []\n        for class_id in sorted(set(converted_classes)):\n            indices = [i for i, value in enumerate(converted_classes) if value == class_id]\n            class_boxes = [nms_boxes[i] for i in indices]\n            class_scores_for_nms = [converted_scores[i] for i in indices]\n            kept = cv2.dnn.NMSBoxes(\n                class_boxes, class_scores_for_nms,\n                CONFIDENCE_THRESHOLD, NMS_IOU_THRESHOLD,\n            )\n            for local_index in np.asarray(kept).reshape(-1) if len(kept) else []:\n                kept_global.append(indices[int(local_index)])\n\n        detections = [\n            (\n                converted_boxes[i],\n                converted_scores[i],\n                converted_classes[i],\n                self.class_names[converted_classes[i]] if converted_classes[i] < len(self.class_names) else f"class_{converted_classes[i]}",\n            )\n            for i in kept_global\n        ]\n        return detections, inference_ms\n\n\ndef put_outlined_text(frame, text, position, scale, colour, thickness=1):\n    cv2.putText(frame, text, position, cv2.FONT_HERSHEY_SIMPLEX, scale, (0, 0, 0), thickness + 2, cv2.LINE_AA)\n    cv2.putText(frame, text, position, cv2.FONT_HERSHEY_SIMPLEX, scale, colour, thickness, cv2.LINE_AA)\n\n\ndef draw_tracks(frame, tracks):\n    for track_id, track in tracks.items():\n        x1, y1, x2, y2 = (int(value) for value in track.box)\n        colour = stable_colour(track_id)\n        cv2.rectangle(frame, (x1, y1), (x2, y2), colour, 2)\n\n        if is_abnormal_behavior_class(track.class_name):\n            behavior_text = f"ABNORMAL: {track.class_name.upper()}  {track.laying_seconds:.2f}s"\n        else:\n            behavior_text = track.class_name.upper()\n\n        put_outlined_text(\n            frame,\n            f"Pig ID {track_id}  {track.confidence:.2f}",\n            (x1, max(22, y1 - 28)),\n            0.52,\n            colour,\n            2,\n        )\n        put_outlined_text(\n            frame,\n            behavior_text,\n            (x1, max(44, y1 - 7)),\n            0.50,\n            colour,\n            2,\n        )\n\n\ndef replace_queue_item(target_queue, value):\n    try:\n        target_queue.get_nowait()\n    except queue.Empty:\n        pass\n    try:\n        target_queue.put_nowait(value)\n    except queue.Full:\n        pass\n\n\ndef inference_worker(detector, input_queue, output_queue, stop_event):\n    raw_tracker = IoUTracker()\n    stable_mapper = StableIDMapper(fps_hint=10.0)\n    behavior_state = {}\n\n    while not stop_event.is_set():\n        try:\n            frame = input_queue.get(timeout=0.1)\n        except queue.Empty:\n            continue\n        try:\n            now = time.perf_counter()\n            detections, inference_ms = detector.detect(frame)\n            raw_tracks = raw_tracker.update(detections, now)\n            mapper_detections = []\n            for raw_id, track in raw_tracks.items():\n                mapper_detections.append({\n                    "track_id": raw_id, "box": track.box,\n                    "confidence": track.confidence, "class_id": track.class_id,\n                    "class_name": track.class_name, "hits": track.hits,\n                    "trail": list(track.trail), "missed": track.missed,\n                })\n\n            stable_detections = stable_mapper.update(mapper_detections, now)\n            snapshot = {}\n            for det in stable_detections:\n                stable_id = int(det["track_id"])\n                class_name = det["class_name"]\n                previous = behavior_state.get(stable_id)\n                gap = det.get("gap_seconds")\n                is_laying = is_laying_class(class_name)\n\n                if previous is None or (gap is not None and gap > GAP_RESET_SEC):\n                    laying_since = now if is_laying else None\n                elif is_laying:\n                    laying_since = previous["laying_since"] or now\n                else:\n                    laying_since = None\n\n                laying_seconds = max(0.0, now - laying_since) if laying_since is not None and is_laying else 0.0\n                behavior_state[stable_id] = {"laying_since": laying_since, "last_seen": now}\n                box = np.asarray(det["box"], dtype=np.float32)\n                snapshot[stable_id] = Track(\n                    box=box.copy(), confidence=float(det["confidence"]),\n                    class_id=int(det["class_id"]), class_name=class_name, missed=0,\n                    trail=list(det["trail"]), hits=int(det["hits"]),\n                    laying_since=laying_since, laying_seconds=laying_seconds,\n                )\n\n            cutoff = now - MAX_LOST_SEC\n            for stable_id, state in list(behavior_state.items()):\n                if state["last_seen"] < cutoff and stable_id not in snapshot:\n                    del behavior_state[stable_id]\n\n            replace_queue_item(output_queue, (snapshot, inference_ms, time.perf_counter(), None))\n        except Exception as error:\n            replace_queue_item(output_queue, ({}, 0.0, time.perf_counter(), str(error)))\n            stop_event.set()\n\n\ndef main():\n    cv2.setUseOptimized(True)\n    cv2.setNumThreads(1)\n\n    detector = YoloOnnxDetector(MODEL_PATH)\n    camera = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)\n    camera.set(cv2.CAP_PROP_FRAME_WIDTH, CAMERA_WIDTH)\n    camera.set(cv2.CAP_PROP_FRAME_HEIGHT, CAMERA_HEIGHT)\n    camera.set(cv2.CAP_PROP_FOURCC, cv2.VideoWriter_fourcc(*"MJPG"))\n    camera.set(cv2.CAP_PROP_BUFFERSIZE, 1)\n    if not camera.isOpened():\n        raise RuntimeError(f"Could not open /dev/video{CAMERA_INDEX}")\n\n    input_queue = queue.Queue(maxsize=1)\n    output_queue = queue.Queue(maxsize=1)\n    stop_event = threading.Event()\n    worker = threading.Thread(target=inference_worker, args=(detector, input_queue, output_queue, stop_event), daemon=True)\n    worker.start()\n\n    latest_tracks = {}\n    latest_inference_ms = 0.0\n    latest_result_time = 0.0\n    last_error = None\n    stable_count = 0\n    pending_count = None\n    pending_count_updates = 0\n    submitted_first_frame = False\n    previous_display_time = time.perf_counter()\n    display_fps = 0.0\n    counted_abnormal_ids = set()\n    abnormal_since = {}\n\n    cv2.namedWindow("YOLO ONNX Pig Tracker", cv2.WINDOW_AUTOSIZE)\n    print("Tracking started. Press Q or Esc in the video window to stop.")\n\n    try:\n        while not stop_event.is_set():\n            loop_started = time.monotonic()\n            ok, frame = camera.read()\n            if not ok or frame is None:\n                time.sleep(0.02)\n                continue\n\n            if input_queue.empty():\n                replace_queue_item(input_queue, frame.copy())\n                submitted_first_frame = True\n\n            try:\n                while True:\n                    latest_tracks, latest_inference_ms, latest_result_time, last_error = output_queue.get_nowait()\n                    candidate_count = len(latest_tracks)\n                    if candidate_count == stable_count:\n                        pending_count = None\n                        pending_count_updates = 0\n                    elif candidate_count == pending_count:\n                        pending_count_updates += 1\n                    else:\n                        pending_count = candidate_count\n                        pending_count_updates = 1\n                    if pending_count_updates >= COUNT_CONFIRMATION_UPDATES:\n                        stable_count = candidate_count\n                        pending_count = None\n                        pending_count_updates = 0\n            except queue.Empty:\n                pass\n\n            display = frame.copy()\n            draw_tracks(display, latest_tracks)\n\n            now = time.perf_counter()\n            instant_fps = 1.0 / max(now - previous_display_time, 1e-6)\n            previous_display_time = now\n            display_fps = instant_fps if display_fps == 0.0 else 0.9 * display_fps + 0.1 * instant_fps\n\n            detection_fps = 1000.0 / latest_inference_ms if latest_inference_ms > 0.0 else 0.0\n            result_age_ms = (now - latest_result_time) * 1000.0 if latest_result_time > 0.0 else 0.0\n            laying_count = sum(1 for track in latest_tracks.values() if is_laying_class(track.class_name))\n            abnormal_behavior_count = sum(\n                1 for track in latest_tracks.values()\n                if is_abnormal_behavior_class(track.class_name)\n            )\n\n            current_abnormal_ids = set()\n            for stable_id, track in latest_tracks.items():\n                if not is_abnormal_behavior_class(track.class_name):\n                    abnormal_since.pop(stable_id, None)\n                    counted_abnormal_ids.discard(stable_id)\n                    continue\n                current_abnormal_ids.add(stable_id)\n                if stable_id not in abnormal_since:\n                    abnormal_since[stable_id] = now\n                if (\n                    stable_id not in counted_abnormal_ids\n                    and now - abnormal_since[stable_id] >= EVENT_CONFIRMATION_SEC\n                ):\n                    increment_controller_metric("abnormal_behavior", 1)\n                    counted_abnormal_ids.add(stable_id)\n\n            for stale_id in set(abnormal_since) - current_abnormal_ids:\n                abnormal_since.pop(stale_id, None)\n            for stale_id in set(counted_abnormal_ids) - current_abnormal_ids:\n                counted_abnormal_ids.discard(stale_id)\n\n            status = (\n                f"Pigs: {stable_count} | Abnormal Behavior: {abnormal_behavior_count} | "\n                f"Model: {detector.input_width}px | "\n                f"Detection: {detection_fps:.1f} FPS ({latest_inference_ms:.0f} ms) | "\n                f"Display: {display_fps:.1f} FPS"\n            )\n            put_outlined_text(display, status, (10, 25), 0.46, (255, 255, 255), 1)\n            put_outlined_text(\n                display,\n                f"Abnormal Behavior: {abnormal_behavior_count}",\n                (10, 50),\n                0.55,\n                (0, 0, 255) if abnormal_behavior_count else (0, 255, 0),\n                2,\n            )\n            # Thermal data is produced by the separate FLIR worker, so it is\n            # intentionally not fabricated or inferred from RGB detections.\n            # The thermal window displays its own High Temperature counter.\n\n            if result_age_ms > 750.0 and latest_inference_ms > 0.0:\n                put_outlined_text(display, f"Boxes are {result_age_ms:.0f} ms old", (10, 48), 0.44, (0, 200, 255), 1)\n\n            if not submitted_first_frame or latest_inference_ms == 0.0:\n                put_outlined_text(display, "Loading first detection...", (10, 70), 0.50, (0, 255, 255), 2)\n\n            if last_error:\n                put_outlined_text(display, "MODEL ERROR - check terminal/log", (10, 92), 0.45, (0, 0, 255), 2)\n\n            cv2.imshow("YOLO ONNX Pig Tracker", cv2.resize(display, (480, 360)))\n            key = cv2.waitKey(1) & 0xFF\n            stop_event.wait(max(0.0, 0.1 - (time.monotonic() - loop_started)))\n            if key in (ord("q"), ord("Q"), 27) or cv2.getWindowProperty("YOLO ONNX Pig Tracker", cv2.WND_PROP_VISIBLE) < 1:\n                break\n\n        if last_error:\n            raise RuntimeError(last_error)\n    finally:\n        stop_event.set()\n        camera.release()\n        cv2.destroyAllWindows()\n\n\n'

def run_worker(kind):
    for variable in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS', 'NUMEXPR_NUM_THREADS'):
        os.environ[variable] = '1'
    cpus = sorted(os.sched_getaffinity(0)) if hasattr(os, 'sched_getaffinity') else []
    capture_cpu = cpus[-1] if len(cpus) >= 4 else None
    if capture_cpu is not None:
        os.sched_setaffinity(0, {cpus[0]} if kind == 'thermal' else set(cpus[1:-1]))
    module = types.ModuleType('working_' + kind)
    module.__file__ = str(Path(__file__).resolve())
    module.os = os
    sys.modules[module.__name__] = module
    source = THERMAL_SOURCE if kind == 'thermal' else YOLO_SOURCE
    exec(compile(source, '<embedded ' + kind + '>', 'exec'), module.__dict__)
    module.cv2.setNumThreads(1)
    print(f"{kind}: process {os.getpid()}, CPU affinity {(sorted(os.sched_getaffinity(0)) if cpus else 'automatic')}", flush=True)
    if kind == 'yolo':
        module.main()
        return
    import fcntl
    import tempfile
    lock = open(Path(tempfile.gettempdir()) / f'pig-lepton-{os.getuid()}.lock', 'w')
    try:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        raise RuntimeError('Another combined thermal worker is already running.')
    module.GUI_UPDATE_MS = 40
    original_display = module.LeptonViewer._display_frame

    def display(self, raw):
        self.received_at = time.monotonic()
        original_display(self, raw)
    module.LeptonViewer._display_frame = display
    root = module.tk.Tk()
    app = module.LeptonViewer(root)
    app.received_at = None
    root.title('Thermal regions — separate from webcam Pig IDs')
    note = module.tk.Label(root, text='TLinear required. Surface estimates only; thermal IDs are not pig IDs.', wraplength=620)
    note.pack()
    freshness = module.tk.Label(root, text='Waiting for first thermal frame', fg='red')
    freshness.pack()
    closing = False

    def close():
        nonlocal closing
        if not closing:
            closing = True
            app.close()
            app.camera.close()
    root.protocol('WM_DELETE_WINDOW', close)
    signal.signal(signal.SIGTERM, lambda *_: root.after(0, close))
    signal.signal(signal.SIGINT, lambda *_: root.after(0, close))

    def check():
        if closing:
            return
        age = None if app.received_at is None else time.monotonic() - app.received_at
        stale = age is None or age > 3.0
        freshness.configure(text='NO FRAME YET' if age is None else f"{('STALE — do not use displayed temperatures' if stale else 'Live')} | last frame {age:.1f}s ago", fg='red' if stale else 'dark green')
        if stale:
            app.temperature_label.configure(text='Temperature unavailable: no recent frame', fg='red')
        root.after(250, check)
    root.after(250, check)
    try:
        root.mainloop()
    finally:
        close()
        lock.close()

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--model', type=Path, default=Path(__file__).with_name('YOLOv8A_SD_best.onnx'))
    parser.add_argument('--yolo-threads', type=int, choices=(1, 2), default=1)
    parser.add_argument('--worker', choices=('thermal', 'yolo'), help=argparse.SUPPRESS)
    args = parser.parse_args()
    if args.worker:
        run_worker(args.worker)
        return
    if not args.model.is_file():
        raise FileNotFoundError(f'Missing model: {args.model}. Put best.onnx beside this file or pass --model /path/model.onnx')
    import tkinter as tk
    root = tk.Tk()
    root.title('Pig Camera Selector')
    root.resizable(False, False)
    tk.Label(root, text='Pig Monitoring Camera', font=('TkDefaultFont', 14, 'bold')).pack(padx=25, pady=(18, 5))
    tk.Label(root, text='Only one camera runs at a time.').pack(padx=25, pady=(0, 12))
    status = tk.Label(root, text='No camera running', font=('TkDefaultFont', 10, 'bold'))
    status.pack(padx=25, pady=(0, 5))
    detail = tk.Label(root, text='', wraplength=430, justify='center')
    detail.pack(padx=25, pady=(0, 8))
    metrics_frame = tk.Frame(root)
    metrics_frame.pack(padx=25, pady=(0, 12), fill='x')
    high_temperature_label = tk.Label(metrics_frame, text='High Temperature: 0', font=('TkDefaultFont', 11, 'bold'), anchor='w')
    high_temperature_label.pack(fill='x')
    abnormal_behavior_label = tk.Label(metrics_frame, text='Abnormal Behavior: 0', font=('TkDefaultFont', 11, 'bold'), anchor='w')
    abnormal_behavior_label.pack(fill='x', pady=(3, 0))
    button_frame = tk.Frame(root)
    button_frame.pack(padx=20, pady=5)
    thermal_button = tk.Button(button_frame, text='Open Thermal Camera', width=24, height=2)
    thermal_button.grid(row=0, column=0, padx=5, pady=5)
    webcam_button = tk.Button(button_frame, text='Open Webcam', width=24, height=2)
    webcam_button.grid(row=0, column=1, padx=5, pady=5)
    stop_button = tk.Button(root, text='Stop Camera', width=24, height=2)
    stop_button.pack(pady=(5, 15))
    log_dir = Path(__file__).resolve().parent / 'camera_logs'
    log_dir.mkdir(exist_ok=True)
    metrics_path = log_dir / 'controller_metrics.json'
    try:
        metrics_path.unlink()
    except FileNotFoundError:
        pass
    env = os.environ.copy()
    env['PIG_STATUS_PATH'] = str(metrics_path)
    env['PIG_MODEL_PATH'] = str(args.model.resolve())
    env['PIG_YOLO_THREADS'] = str(args.yolo_threads)
    active_kind = None
    active_process = None
    active_log = None
    switching = False
    closing = False

    def reset_metrics():
        high_temperature_label.configure(text='High Temperature: 0')
        abnormal_behavior_label.configure(text='Abnormal Behavior: 0')
        try:
            metrics_path.unlink()
        except FileNotFoundError:
            pass

    def poll_metrics():
        if closing:
            return
        high_temperature = 0
        abnormal_behavior = 0
        try:
            with metrics_path.open('r', encoding='utf-8') as handle:
                metrics = json.load(handle)
            high_temperature = max(0, int(metrics.get('high_temperature', 0)))
            abnormal_behavior = max(0, int(metrics.get('abnormal_behavior', 0)))
        except (OSError, ValueError, TypeError):
            pass
        high_temperature_label.configure(text=f'High Temperature: {high_temperature}', fg='dark red' if high_temperature else 'black')
        abnormal_behavior_label.configure(text=f'Abnormal Behavior: {abnormal_behavior}', fg='dark red' if abnormal_behavior else 'black')
        root.after(250, poll_metrics)

    def update_buttons():
        if closing or switching:
            state = tk.DISABLED
        else:
            state = tk.NORMAL
        thermal_button.configure(state=state)
        webcam_button.configure(state=state)
        stop_button.configure(state=state)

    def terminate_active():
        nonlocal active_kind, active_process, active_log
        process = active_process
        log = active_log
        active_process = None
        active_kind = None
        active_log = None
        if process is not None:
            if process.poll() is None:
                try:
                    os.killpg(process.pid, signal.SIGTERM)
                except ProcessLookupError:
                    pass
                try:
                    process.wait(timeout=3.0)
                except subprocess.TimeoutExpired:
                    try:
                        os.killpg(process.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                    try:
                        process.wait(timeout=2.0)
                    except subprocess.TimeoutExpired:
                        pass
        if log is not None:
            try:
                log.close()
            except Exception:
                pass

    def start_camera(kind):
        nonlocal active_kind, active_process, active_log
        reset_metrics()
        log_path = log_dir / f'{kind}.log'
        log = open(log_path, 'w', buffering=1)
        try:
            process = subprocess.Popen([sys.executable, '-u', str(Path(__file__).resolve()), '--worker', kind], env=env, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
        except Exception:
            log.close()
            raise
        active_kind = kind
        active_process = process
        active_log = log

    def switch_camera(kind):
        nonlocal switching
        if closing or switching:
            return
        if active_kind == kind and active_process is not None:
            if active_process.poll() is None:
                return
        switching = True
        update_buttons()
        try:
            old_name = {'thermal': 'Thermal Camera', 'yolo': 'Webcam'}.get(active_kind, 'camera')
            if active_process is not None:
                status.configure(text=f'Closing {old_name}...')
                detail.configure(text='Releasing the previous camera first.')
                root.update_idletasks()
                terminate_active()
            new_name = 'Thermal Camera' if kind == 'thermal' else 'Webcam'
            status.configure(text=f'Starting {new_name}...')
            detail.configure(text='Only this camera will be active.')
            root.update_idletasks()
            start_camera(kind)
            status.configure(text=f'{new_name} is active')
            detail.configure(text='Thermal camera: latest-frame display with separate SPI acquisition.' if kind == 'thermal' else 'Webcam: YOLO ONNX pig detection and tracking.')
        except Exception as error:
            terminate_active()
            status.configure(text='Camera failed to start')
            detail.configure(text=str(error))
        finally:
            switching = False
            update_buttons()

    def stop_camera():
        nonlocal switching
        if closing or switching:
            return
        switching = True
        update_buttons()
        try:
            if active_process is not None:
                status.configure(text='Closing camera...')
                detail.configure(text='Releasing camera hardware.')
                root.update_idletasks()
                terminate_active()
            status.configure(text='No camera running')
            detail.configure(text='')
            reset_metrics()
        finally:
            switching = False
            update_buttons()

    def poll_process():
        if closing:
            return
        if active_process is not None:
            code = active_process.poll()
            if code is not None and (not switching):
                finished_kind = active_kind
                terminate_active()
                name = 'Thermal Camera' if finished_kind == 'thermal' else 'Webcam'
                status.configure(text=f'{name} stopped')
                detail.configure(text=f'Check camera_logs/{finished_kind}.log for details.')
        root.after(300, poll_process)

    def shutdown():
        nonlocal closing
        if closing:
            return
        closing = True
        update_buttons()
        terminate_active()
        root.destroy()
    thermal_button.configure(command=lambda: switch_camera('thermal'))
    webcam_button.configure(command=lambda: switch_camera('yolo'))
    stop_button.configure(command=stop_camera)
    root.protocol('WM_DELETE_WINDOW', shutdown)
    signal.signal(signal.SIGTERM, lambda *_: root.after(0, shutdown))
    signal.signal(signal.SIGINT, lambda *_: root.after(0, shutdown))
    update_buttons()
    root.after(250, poll_metrics)
    root.after(300, poll_process)
    root.after(100, lambda: switch_camera('thermal'))
    try:
        root.mainloop()
    finally:
        shutdown()
if __name__ == '__main__':
    main()